package com.oms.inventory;
import com.oms.inventory.service.impl.*;
import com.oms.inventory.model.entity.WmsInventoryBatch;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class StockMovementTest {
 OrderStockTest f;StockMovementService service;
 @BeforeAll static void start(){OrderStockTest.start();}
 @AfterAll static void stop(){OrderStockTest.stop();}
 @BeforeEach void setup(){f=new OrderStockTest();f.clear();for(String t:Arrays.asList("oms_stock_movement_event","oms_stock_transfer_line","oms_stock_transfer"))f.db.update("DELETE FROM "+t);f.seed(10,0);WmsInventoryBatch b=new WmsInventoryBatch();b.setCompanyCode("VERIFY");b.setSkuSn("A");b.setStoreCode("W1");b.setBatchCode("B1");b.setZpActualNumber(0);b.setCpActualNumber(3);f.inventory.receivePurchase(b,"WMS_RECEIPT_9001");service=f.context.getBean(StockMovementService.class);}
 Map<String,Object>m(Object...a){Map<String,Object>r=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)r.put(a[i].toString(),a[i+1]);return r;}
 long n(String sql){return f.n(sql);}
 Map<String,Object>line(String grade,int q){Map<String,Object>b=f.db.queryForMap("SELECT * FROM wms_inventory_batch WHERE sku_sn='A'");return m("line_key",1,"source_batch_id",b.get("id"),"sku_sn","A","source_store","W1","target_store","W2","batch_code","B1","inventory_type",grade,"quantity",q,"unit_cost",b.get("transaction_price"),"stock_unit","件");}
 Map<String,Object>reserve(String sn,String grade,int q){return m("document_sn",sn,"actor","tester","lines",Collections.singletonList(line(grade,q)));}
 Map<String,Object>fact(String sn,String message,String type,int q){return m("document_sn",sn,"message_id",message,"actor","WMS","lines",Collections.singletonList(m("line_key",1,"sku_sn","A","batch_code","B1","inventory_type",type,"quantity",q)));}
 long transit(){return n("SELECT COALESCE(SUM(out_quantity-in_quantity-recovered_quantity),0) FROM oms_stock_transfer_line");}
 @Test void draftReadDoesNotReserveAndSnapshotIncludesSeparateTransit(){Map<String,Object>s=service.snapshot("VERIFY",m("stores",Arrays.asList("W1","W2"),"skus",Collections.singletonList("A")));assertEquals(1,((List)s.get("batches")).size());assertEquals(13,n("SELECT total_stock FROM oms_inventory"));assertEquals(0,transit());}
 @Test void fullCheckDiscoveryIsKeysetScopedAndPreservesZeroInventoryRecords(){Map<String,Object>first=service.discover("VERIFY",m("stores",Collections.singletonList("W1"),"cursor",0,"maximum",0,"started",false));assertEquals(1,((List)first.get("rows")).size());assertEquals(true,first.get("done"));Map<String,Object>end=service.discover("VERIFY",m("stores",Collections.singletonList("W1"),"cursor",first.get("cursor"),"maximum",first.get("maximum"),"started",true));assertTrue(((List)end.get("rows")).isEmpty());assertTrue(((List)service.discover("OTHER",m("stores",Collections.singletonList("W1"),"cursor",0,"maximum",0,"started",false)).get("rows")).isEmpty());assertTrue(((List)service.discover("VERIFY",m("stores",Collections.singletonList("W2"),"cursor",0,"maximum",0,"started",false)).get("rows")).isEmpty());f.db.update("UPDATE wms_inventory SET zp_actual_number=0,cp_actual_number=0 WHERE company_code='VERIFY'");assertEquals(1,((List)service.discover("VERIFY",m("stores",Collections.singletonList("W1"),"cursor",0,"maximum",0,"started",false)).get("rows")).size());}
 @Test void checkSearchReadsOnlyScopedInventoryAndEscapesWildcards(){assertEquals(1,((List)service.checkSearch("VERIFY",m("stores",Collections.singletonList("W1"),"keyword","A")).get("rows")).size());assertTrue(((List)service.checkSearch("OTHER",m("stores",Collections.singletonList("W1"),"keyword","A")).get("rows")).isEmpty());assertTrue(((List)service.checkSearch("VERIFY",m("stores",Collections.singletonList("W1"),"keyword","%")).get("rows")).isEmpty());}
 @Test void fullTransferPreservesCostBatchCompanyOwnedAndJournal(){service.execute("VERIFY","reserve",reserve("DBFULL","ZP",10));assertEquals(0,n("SELECT available_stock FROM oms_inventory"));service.execute("VERIFY","out",fact("DBFULL","O1","ZP",10));assertEquals(3,n("SELECT total_stock FROM oms_inventory"));assertEquals(10,transit());service.execute("VERIFY","in",fact("DBFULL","I1","ZP",10));assertEquals(13,n("SELECT total_stock FROM oms_inventory"));assertEquals(10,n("SELECT available_stock FROM oms_inventory"));assertEquals(0,transit());assertEquals(2,n("SELECT COUNT(*) FROM wms_inventory_batch WHERE batch_code='B1'"));assertEquals(1,n("SELECT COUNT(DISTINCT transaction_price) FROM wms_inventory_batch"));assertEquals(1,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='TRANSFER_OUT'"));}
 @Test void tenOutEightReceivedKeepsTwoNonSaleableTransit(){service.execute("VERIFY","reserve",reserve("DBPART","ZP",10));service.execute("VERIFY","out",fact("DBPART","O","ZP",10));service.execute("VERIFY","in",fact("DBPART","I","ZP",8));assertEquals(11,n("SELECT total_stock FROM oms_inventory"));assertEquals(8,n("SELECT available_stock FROM oms_inventory"));assertEquals(2,transit());assertEquals(13,n("SELECT total_stock FROM oms_inventory")+transit());ProductInventoryQueryService view=new ProductInventoryQueryService();org.springframework.test.util.ReflectionTestUtils.setField(view,"jdbc",f.db);Map<String,Object>row=(Map<String,Object>)view.list("VERIFY","A",false,1,20).getRows().get(0);assertEquals(13L,row.get("ownedStock"));assertEquals(2L,row.get("transitStock"));}
 @Test void partialOutboundCannotReceiveMoreThanActuallyShipped(){service.execute("VERIFY","reserve",reserve("DBCAP","ZP",10));service.execute("VERIFY","out",fact("DBCAP","O","ZP",4));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","in",fact("DBCAP","I","ZP",5)));assertEquals(4,transit());assertEquals(6,n("SELECT allocated_stock FROM oms_inventory"));}
 @Test void cancelReleasesOnlyUnshippedAndDoesNotRestoreTransit(){service.execute("VERIFY","reserve",reserve("DBSTOP","ZP",10));service.execute("VERIFY","out",fact("DBSTOP","O","ZP",4));Map<String,Object>cmd=m("document_sn","DBSTOP","message_id","STOP","actor","tester");service.execute("VERIFY","release",cmd);service.execute("VERIFY","release",cmd);assertEquals(9,n("SELECT total_stock FROM oms_inventory"));assertEquals(6,n("SELECT available_stock FROM oms_inventory"));assertEquals(0,n("SELECT allocated_stock FROM oms_inventory"));assertEquals(4,transit());assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","out",fact("DBSTOP","LATE","ZP",1)));service.execute("VERIFY","in",fact("DBSTOP","I","ZP",4));assertEquals(13,n("SELECT total_stock FROM oms_inventory"));}
 @Test void independentRecoveryConsumesTransitWithoutErasingOutbound(){service.execute("VERIFY","reserve",reserve("DBBACK","ZP",10));service.execute("VERIFY","out",fact("DBBACK","O","ZP",10));service.execute("VERIFY","in",fact("DBBACK","I","ZP",8));service.execute("VERIFY","recover",fact("DBBACK","R","ZP",2));service.execute("VERIFY","recover",fact("DBBACK","R","ZP",2));assertEquals(0,transit());assertEquals(13,n("SELECT total_stock FROM oms_inventory"));assertEquals(2,n("SELECT zp_actual_number FROM wms_inventory WHERE store_code='W1'"));assertEquals(1,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='TRANSFER_OUT'"));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","in",fact("DBBACK","EXTRA","ZP",1)));}
 @Test void badStockStaysNonSaleableAcrossHoldsTransitAndReceiving(){service.execute("VERIFY","reserve",reserve("DBBAD","CP",3));assertEquals(0,n("SELECT frozen_stock FROM oms_inventory"));service.execute("VERIFY","out",fact("DBBAD","O","CP",3));service.execute("VERIFY","in",fact("DBBAD","I","CP",2));assertEquals(12,n("SELECT total_stock FROM oms_inventory"));assertEquals(10,n("SELECT available_stock FROM oms_inventory"));assertEquals(2,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(1,transit());}
 @Test void badStockRemainingReleaseRestoresFrozenOnly(){service.execute("VERIFY","reserve",reserve("DBBADSTOP","CP",3));service.execute("VERIFY","out",fact("DBBADSTOP","O","CP",1));service.execute("VERIFY","release",m("document_sn","DBBADSTOP","message_id","STOP","actor","tester"));assertEquals(2,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(10,n("SELECT available_stock FROM oms_inventory"));assertEquals(1,transit());}
 @Test void duplicateReceiptAndChangedMessageCannotDoublePost(){service.execute("VERIFY","reserve",reserve("DBID","ZP",5));Map<String,Object>cmd=fact("DBID","X","ZP",3);service.execute("VERIFY","out",cmd);service.execute("VERIFY","out",cmd);assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","out",fact("DBID","X","ZP",2)));assertEquals(3,transit());}
 @Test void wrongGradeBatchOrCompanyCannotPost(){service.execute("VERIFY","reserve",reserve("DBBIND","ZP",5));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","out",fact("DBBIND","X","CP",1)));Map<String,Object>cmd=fact("DBBIND","Y","ZP",1);((Map)((List)cmd.get("lines")).get(0)).put("batch_code","OTHER");assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","out",cmd));assertThrows(IllegalArgumentException.class,()->service.report("OTHER","DBBIND"));assertEquals(0,transit());}
 @Test void orderPublicClaimsRemainProtected(){f.execute("register",f.command("9001",9,true));f.execute("reserve",f.command("9001",9,true));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","reserve",reserve("DBCLAIM","ZP",2)));assertEquals(0,n("SELECT COUNT(*) FROM oms_stock_transfer"));}
 @Test void concurrentReservationsDoNotOverdraw()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Callable<Boolean>>jobs=new ArrayList<>();for(String sn:Arrays.asList("DBR1","DBR2"))jobs.add(()->{try{service.execute("VERIFY","reserve",reserve(sn,"ZP",7));return true;}catch(IllegalArgumentException e){return false;}});int wins=0;for(Future<Boolean>x:pool.invokeAll(jobs))if(x.get())wins++;assertEquals(1,wins);assertEquals(7,n("SELECT allocated_stock FROM oms_inventory"));}finally{pool.shutdownNow();}}
 @Test void concurrentDestinationAndRecoveryShareOneTransitCap()throws Exception{service.execute("VERIFY","reserve",reserve("DBRACE","ZP",10));service.execute("VERIFY","out",fact("DBRACE","O","ZP",10));ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Callable<Boolean>>jobs=new ArrayList<>();for(String a:Arrays.asList("in","recover"))jobs.add(()->{try{service.execute("VERIFY",a,fact("DBRACE",a,"ZP",7));return true;}catch(IllegalArgumentException e){return false;}});int wins=0;for(Future<Boolean>x:pool.invokeAll(jobs))if(x.get())wins++;assertEquals(1,wins);assertEquals(3,transit());}finally{pool.shutdownNow();}}
 Map<String,Object>adjust(String sn,int q){Map<String,Object>s=service.snapshot("VERIFY",m("stores",Arrays.asList("W1","W2"),"skus",Collections.singletonList("A")));Map<String,Object>b=((List<Map<String,Object>>)s.get("batches")).get(0);return m("document_sn",sn,"actor","reviewer","evidence","仓库盘点及无待入账凭证","snapshot",s,"lines",Collections.singletonList(m("sku_sn","A","store_code","W1","batch_code","B1","inventory_type","ZP","quantity",q,"unit_cost",b.get("transaction_price"))));}
 @Test void independentAdjustmentIsVersionCheckedAndIdempotent(){Map<String,Object>cmd=adjust("TZLOSS",-2);service.execute("VERIFY","adjust",cmd);service.execute("VERIFY","adjust",cmd);assertEquals(11,n("SELECT total_stock FROM oms_inventory"));assertEquals(8,n("SELECT available_stock FROM oms_inventory"));assertEquals(1,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='COUNT_LOSS'"));}
 @Test void movementAfterSnapshotBlocksAdjustment(){Map<String,Object>cmd=adjust("TZSTALE",-1);service.execute("VERIFY","reserve",reserve("DBAFTER","ZP",1));assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","adjust",cmd));assertEquals(13,n("SELECT total_stock FROM oms_inventory"));}
 @Test void twoAdjustmentsOnSameSnapshotCannotApplyTwice(){Map<String,Object>a=adjust("TZFIRST",-1),b=adjust("TZSECOND",-1);service.execute("VERIFY","adjust",a);assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","adjust",b));assertEquals(12,n("SELECT total_stock FROM oms_inventory"));}
 @Test void lossCannotConsumeReservedOrdersAndRollsBack(){f.execute("register",f.command("9001",9,true));f.execute("reserve",f.command("9001",9,true));Map<String,Object>cmd=adjust("TZPROTECT",-2);assertThrows(IllegalArgumentException.class,()->service.execute("VERIFY","adjust",cmd));assertEquals(13,n("SELECT total_stock FROM oms_inventory"));assertEquals(0,n("SELECT COUNT(*) FROM oms_stock_movement_event"));}
 @Test void stockSignalsIncludeSourceHoldAndDestinationReceipt(){long before=n("SELECT COALESCE(SUM(revision),0) FROM oms_allocation_stock_signal");service.execute("VERIFY","reserve",reserve("DBSIGNAL","ZP",2));service.execute("VERIFY","out",fact("DBSIGNAL","O","ZP",2));service.execute("VERIFY","in",fact("DBSIGNAL","I","ZP",2));assertTrue(n("SELECT SUM(revision) FROM oms_allocation_stock_signal")>before);assertEquals(1,n("SELECT COUNT(*) FROM oms_allocation_stock_signal WHERE company_code='VERIFY' AND sku_sn='A' AND store_code='W2'"));}

 @Test void channelAvailabilityFallsOnHoldAndReturnsOnlyAfterDestinationReceipt(){
  f.db.update("UPDATE oms_channel_inventory SET quota_stock=20,stock_scope_json='[\"W1\",\"W2\"]' WHERE company_code='VERIFY' AND channel_id=1 AND sku_sn='A'");PlatformStockSnapshot calculator=f.context.getBean(PlatformStockSnapshot.class);Map<String,Object>input=m("channel_id",1,"allow_public_stock",true,"allowed_warehouses",Arrays.asList("W1","W2"),"components",Collections.singletonList(m("sku_sn","A","quantity",1)));
  assertEquals(10L,calculator.snapshot("VERIFY",input).get("available"));service.execute("VERIFY","reserve",reserve("DBCHANNEL","ZP",2));assertEquals(8L,calculator.snapshot("VERIFY",input).get("available"));service.execute("VERIFY","out",fact("DBCHANNEL","O","ZP",2));assertEquals(8L,calculator.snapshot("VERIFY",input).get("available"));service.execute("VERIFY","in",fact("DBCHANNEL","I","ZP",2));assertEquals(10L,calculator.snapshot("VERIFY",input).get("available"));f.db.update("UPDATE oms_channel_inventory SET stock_scope_json='[\"W1\"]' WHERE company_code='VERIFY' AND channel_id=1 AND sku_sn='A'");assertEquals(8L,calculator.snapshot("VERIFY",input).get("available"));
  ProductInventoryQueryService view=new ProductInventoryQueryService();org.springframework.test.util.ReflectionTestUtils.setField(view,"jdbc",f.db);Map<String,Object>row=(Map<String,Object>)view.list("VERIFY","A",false,1,20).getRows().get(0);assertEquals(13L,row.get("ownedStock"));assertEquals(0L,row.get("transitStock"));
 }
}
